template <class Character, class Traits, class Allocator>
class basic_string
{
public:
	basic_string(const Character *text, const Allocator &allocator = Allocator());

	~basic_string()
	{
		if (m_start)
		{
			const unsigned int bytes =
				(unsigned int)(m_storageEnd - m_start) * sizeof(Character);
			if (bytes > 128)
				::operator delete(m_start);
			else
				__node_alloc<true, 0>::_M_deallocate(m_start, bytes);
		}
	}

	const Character *c_str() const { return m_start; }

private:
	Character *m_start;
	Character *m_end;
	Character *m_storageEnd;
};

typedef basic_string<WideChar, char_traits<WideChar>, allocator<WideChar> > wstring;
