enum { kUtf8CodePage = 0xfde9 };

// ?b_006617d0@@YAXXZ address-derived; U-traits reloc candidate and V-traits
// STLport constructor ABI are not yet proven to be one identity.
_STL::wstring MultiByteToWideCharSingleLine(const char *orig)
{
	int len = 2 * (int)strlen(orig);
	WideChar *dest = (WideChar *)operator new[](
		(unsigned)(len + 1) * sizeof(WideChar));
	memset(dest, 0, (unsigned)(len + 1) * sizeof(WideChar));
	MultiByteToWideChar(kUtf8CodePage, 0, orig, -1, dest, len);

	WideChar *c;
	do
	{
		c = wcschr(dest, 0x000a);
		if (c)
			*c = 0x0020;
	} while (c != 0);
	do
	{
		c = wcschr(dest, 0x000d);
		if (c)
			*c = 0x0020;
	} while (c != 0);

	_STL::wstring ret(dest);
	operator delete[](dest);
	return ret;
}

