struct BuddyResponse
{
	enum ResponseType
	{
		BUDDYRESPONSE_LOGIN,
		BUDDYRESPONSE_DISCONNECT,
		BUDDYRESPONSE_MESSAGE,
		BUDDYRESPONSE_REQUEST
	};

	ResponseType buddyResponseType;
	GPProfile profile;
	int result;
	union
	{
		struct
		{
			unsigned int date;
			char nick[32];
			wchar_t text[128];
		} message;

		struct
		{
			char identity[0x56];
			wchar_t text[1025];
		} request;

		struct
		{
			char nick[31];
			char email[51];
			char countrycode[3];
			char location[256];
			int status;
			char statusString[256];
		} status;
	} arg;
};

